#!/usr/bin/env python3
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
INSTALLER = ROOT / "scripts/field/install_one_time_capture.command"
ORIGIN_HELPER = ROOT / "scripts/ci/capture_signed_app_build_origin_custody.py"
ORIGIN_TEST = ROOT / "scripts/ci/tests/test_capture_signed_app_pre_stage_origin.py"
INSTALL_HELPER = ROOT / "scripts/ci/capture_signed_app_install_custody.py"
INSTALL_TEST = ROOT / "scripts/ci/tests/test_capture_signed_app_install_custody.py"
INSTALL_WORKFLOW = ROOT / ".github/workflows/capture-signed-app-install-custody.yml"
FIELD_WORKFLOW = ROOT / ".github/workflows/capture-field-build-provenance.yml"

ORIGIN_HELPER_SOURCE = '#!/usr/bin/env python3\nfrom __future__ import annotations\n\nimport argparse\nimport base64\nimport grp\nimport json\nimport os\nimport pwd\nimport secrets\nimport shutil\nimport signal\nimport stat\nimport subprocess\nimport sys\nimport tempfile\nimport time\nfrom pathlib import Path\nfrom typing import Callable, Sequence\n\nDERIVED_PREFIX = "nembra-authenticated-capture-derived."\nSTAGE_PREFIX = "nembra-authenticated-capture-install."\nDEFAULT_APP_RELATIVE = Path("Build/Products/Debug-iphoneos/Nembra Capture.app")\nDERIVED_PLACEHOLDER = "__NEMBRA_PROTECTED_DERIVED__"\n\n\nclass BuildOriginCustodyError(RuntimeError):\n    pass\n\n\ndef _require_real_private_tmp() -> Path:\n    root = Path("/private/tmp")\n    try:\n        metadata = root.lstat()\n    except OSError as error:\n        raise BuildOriginCustodyError("/private/tmp is unavailable") from error\n    if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):\n        raise BuildOriginCustodyError("/private/tmp is not one real directory")\n    return root\n\n\ndef _invoking_identity() -> tuple[str, int, int, str, tuple[int, ...]]:\n    if os.geteuid() != 0:\n        raise BuildOriginCustodyError("build-origin custody must run as root through sudo")\n    raw_uid = os.environ.get("SUDO_UID", "")\n    raw_gid = os.environ.get("SUDO_GID", "")\n    sudo_user = os.environ.get("SUDO_USER", "")\n    if not raw_uid.isdigit() or not raw_gid.isdigit() or not sudo_user:\n        raise BuildOriginCustodyError("sudo did not expose one invoking-user identity")\n    uid = int(raw_uid)\n    gid = int(raw_gid)\n    if uid <= 0:\n        raise BuildOriginCustodyError("root may not be the field-build invoking identity")\n    account = pwd.getpwuid(uid)\n    if account.pw_name != sudo_user or account.pw_gid != gid:\n        raise BuildOriginCustodyError("sudo invoking identity does not match the local account database")\n    groups = tuple(sorted(set(os.getgrouplist(account.pw_name, gid))))\n    return account.pw_name, uid, gid, account.pw_dir, groups\n\n\ndef _choose_capability_gid(\n    invoking_groups: Sequence[int],\n    *,\n    randbelow: Callable[[int], int] = secrets.randbelow,\n) -> int:\n    occupied = {entry.gr_gid for entry in grp.getgrall()}\n    occupied.update(int(value) for value in invoking_groups)\n    occupied.add(0)\n    low = 1 << 29\n    span = (1 << 30) - low\n    for _ in range(256):\n        candidate = low + randbelow(span)\n        if candidate not in occupied:\n            return candidate\n    raise BuildOriginCustodyError("could not allocate an isolated one-run build capability gid")\n\n\ndef _drop_credentials(uid: int, gid: int, groups: Sequence[int]) -> Callable[[], None]:\n    normalized_groups = tuple(sorted(set(int(value) for value in groups)))\n\n    def demote() -> None:\n        os.setgroups(list(normalized_groups))\n        os.setgid(gid)\n        os.setuid(uid)\n\n    return demote\n\n\ndef _invalidate_invoker_sudo(uid: int, gid: int, groups: Sequence[int], env: dict[str, str]) -> None:\n    demote = _drop_credentials(uid, gid, groups)\n    revoke = subprocess.run(\n        ["/usr/bin/sudo", "-K"],\n        env=env,\n        stdin=subprocess.DEVNULL,\n        stdout=subprocess.DEVNULL,\n        stderr=subprocess.DEVNULL,\n        preexec_fn=demote,\n        check=False,\n    )\n    if revoke.returncode != 0:\n        raise BuildOriginCustodyError("could not invalidate invoking-user sudo timestamp before build custody")\n    probe = subprocess.run(\n        ["/usr/bin/sudo", "-n", "/usr/bin/true"],\n        env=env,\n        stdin=subprocess.DEVNULL,\n        stdout=subprocess.DEVNULL,\n        stderr=subprocess.DEVNULL,\n        preexec_fn=demote,\n        check=False,\n    )\n    if probe.returncode == 0:\n        raise BuildOriginCustodyError(\n            "noninteractive sudo remains available after invalidation; build-origin isolation cannot be established"\n        )\n\n\ndef _child_environment(user: str, home: str) -> dict[str, str]:\n    environment = {\n        "HOME": home,\n        "USER": user,\n        "LOGNAME": user,\n        "PATH": "/usr/bin:/bin:/usr/sbin:/sbin",\n        "TMPDIR": "/tmp",\n    }\n    for key in ("LANG", "LC_ALL", "LC_CTYPE", "TERM", "__CF_USER_TEXT_ENCODING"):\n        value = os.environ.get(key)\n        if value:\n            environment[key] = value\n    return environment\n\n\ndef _replace_derived_placeholder(command: Sequence[str], derived_root: Path) -> list[str]:\n    if not command:\n        raise BuildOriginCustodyError("no guarded build command was supplied")\n    matches = sum(argument.count(DERIVED_PLACEHOLDER) for argument in command)\n    if matches != 1:\n        raise BuildOriginCustodyError("guarded build command must contain exactly one protected DerivedData placeholder")\n    return [argument.replace(DERIVED_PLACEHOLDER, str(derived_root)) for argument in command]\n\n\ndef _validate_app_relative(path: Path) -> Path:\n    if path.is_absolute() or not path.parts or any(part in ("", ".", "..") for part in path.parts):\n        raise BuildOriginCustodyError("app-relative path must remain strictly beneath protected DerivedData")\n    return path\n\n\ndef _assert_real_ancestry(root: Path, relative: Path) -> Path:\n    current = root\n    for component in relative.parts:\n        current = current / component\n        try:\n            metadata = current.lstat()\n        except OSError as error:\n            raise BuildOriginCustodyError(f"expected build output is missing: {current}") from error\n        if stat.S_ISLNK(metadata.st_mode):\n            raise BuildOriginCustodyError(f"build-output ancestry contains a symlink: {current}")\n    if not current.is_dir():\n        raise BuildOriginCustodyError("build output app is not one real directory")\n    return current\n\n\ndef _load_fingerprint_helper(encoded: str):\n    try:\n        source = base64.b64decode(encoded, validate=True)\n    except Exception as error:\n        raise BuildOriginCustodyError("accepted install-custody helper transport is malformed") from error\n    namespace = {\n        "__name__": "nembra_signed_app_install_custody",\n        "__file__": "<accepted-signed-app-install-custody>",\n    }\n    try:\n        exec(\n            compile(source, "<accepted-signed-app-install-custody>", "exec", dont_inherit=True),\n            namespace,\n        )\n    except Exception as error:\n        raise BuildOriginCustodyError("accepted install-custody helper could not be loaded") from error\n    fingerprint = namespace.get("fingerprint")\n    if not callable(fingerprint):\n        raise BuildOriginCustodyError("accepted install-custody helper exposes no fingerprint function")\n    return fingerprint\n\n\ndef _terminate_remaining_process_group(process_group: int) -> None:\n    try:\n        os.killpg(process_group, signal.SIGTERM)\n    except ProcessLookupError:\n        return\n    deadline = time.monotonic() + 3.0\n    while time.monotonic() < deadline:\n        try:\n            os.killpg(process_group, 0)\n        except ProcessLookupError:\n            return\n        time.sleep(0.05)\n    try:\n        os.killpg(process_group, signal.SIGKILL)\n    except ProcessLookupError:\n        return\n    deadline = time.monotonic() + 2.0\n    while time.monotonic() < deadline:\n        try:\n            os.killpg(process_group, 0)\n        except ProcessLookupError:\n            return\n        time.sleep(0.05)\n    raise BuildOriginCustodyError("guarded build left a live process in its isolated process group")\n\n\ndef _prepare_derived(private_tmp: Path, capability_gid: int) -> Path:\n    derived = Path(tempfile.mkdtemp(prefix=DERIVED_PREFIX, dir=private_tmp))\n    os.chown(derived, 0, capability_gid)\n    os.chmod(derived, 0o770)\n    return derived\n\n\ndef _copy_to_stage(source_app: Path, private_tmp: Path) -> tuple[Path, Path]:\n    stage_root = Path(tempfile.mkdtemp(prefix=STAGE_PREFIX, dir=private_tmp))\n    os.chown(stage_root, 0, 0)\n    os.chmod(stage_root, 0o700)\n    stage_app = stage_root / "Nembra Capture.app"\n    subprocess.run(\n        ["/usr/bin/ditto", "--noacl", str(source_app), str(stage_app)],\n        stdin=subprocess.DEVNULL,\n        stdout=subprocess.DEVNULL,\n        stderr=subprocess.PIPE,\n        text=True,\n        check=True,\n    )\n    acl = subprocess.run(\n        ["/usr/bin/find", str(stage_root), "-acl", "-print", "-quit"],\n        stdin=subprocess.DEVNULL,\n        stdout=subprocess.PIPE,\n        stderr=subprocess.PIPE,\n        text=True,\n        check=True,\n    ).stdout.strip()\n    if acl:\n        raise BuildOriginCustodyError(f"protected stage retained an ACL: {acl}")\n    for current_root, directories, files in os.walk(stage_root, topdown=False, followlinks=False):\n        current = Path(current_root)\n        for name in files:\n            candidate = current / name\n            os.chown(candidate, 0, 0, follow_symlinks=False)\n        for name in directories:\n            candidate = current / name\n            os.chown(candidate, 0, 0, follow_symlinks=False)\n        os.chown(current, 0, 0, follow_symlinks=False)\n    os.chmod(stage_root, 0o755)\n    return stage_root, stage_app\n\n\ndef run_custodied_build(\n    command: Sequence[str],\n    *,\n    app_relative: Path,\n    fingerprint_helper_base64: str,\n) -> tuple[Path, str]:\n    private_tmp = _require_real_private_tmp()\n    user, uid, gid, home, invoking_groups = _invoking_identity()\n    child_env = _child_environment(user, home)\n    _invalidate_invoker_sudo(uid, gid, invoking_groups, child_env)\n\n    capability_gid = _choose_capability_gid(invoking_groups)\n    derived_root: Path | None = None\n    stage_root: Path | None = None\n    process: subprocess.Popen[str] | None = None\n    fingerprint = _load_fingerprint_helper(fingerprint_helper_base64)\n    try:\n        derived_root = _prepare_derived(private_tmp, capability_gid)\n        guarded_command = _replace_derived_placeholder(command, derived_root)\n        child_groups = tuple(sorted(set(invoking_groups) | {capability_gid}))\n        process = subprocess.Popen(\n            guarded_command,\n            cwd=os.getcwd(),\n            env=child_env,\n            stdin=None,\n            stdout=sys.stderr,\n            stderr=sys.stderr,\n            text=True,\n            start_new_session=True,\n            preexec_fn=_drop_credentials(uid, gid, child_groups),\n        )\n        returncode = process.wait()\n        _terminate_remaining_process_group(process.pid)\n        if returncode != 0:\n            raise BuildOriginCustodyError(f"guarded field build failed with exit status {returncode}")\n\n        # Revoke the transient build capability from the filesystem before any\n        # bundle bytes are hashed or copied. Any same-UID process lacking the\n        # one-run supplementary gid was excluded throughout the compiler window;\n        # any surviving descendant in the build process group was terminated above.\n        os.chown(derived_root, 0, 0)\n        os.chmod(derived_root, 0o700)\n\n        source_app = _assert_real_ancestry(derived_root, _validate_app_relative(app_relative))\n        source_fingerprint = str(fingerprint(source_app))\n        if len(source_fingerprint) != 64 or any(ch not in "0123456789abcdef" for ch in source_fingerprint):\n            raise BuildOriginCustodyError("build-produced app fingerprint is malformed")\n\n        stage_root, stage_app = _copy_to_stage(source_app, private_tmp)\n        staged_fingerprint = str(fingerprint(stage_app))\n        if staged_fingerprint != source_fingerprint:\n            raise BuildOriginCustodyError("protected stage differs from the isolated xcodebuild-produced app")\n        return stage_root, source_fingerprint\n    except subprocess.CalledProcessError as error:\n        detail = (error.stderr or "").strip()\n        raise BuildOriginCustodyError(\n            "protected signed-app staging command failed" + (f": {detail}" if detail else "")\n        ) from error\n    finally:\n        if process is not None and process.poll() is None:\n            try:\n                os.killpg(process.pid, signal.SIGKILL)\n            except ProcessLookupError:\n                pass\n            process.wait()\n        if derived_root is not None:\n            shutil.rmtree(derived_root, ignore_errors=True)\n        if sys.exc_info()[0] is not None and stage_root is not None:\n            shutil.rmtree(stage_root, ignore_errors=True)\n\n\ndef _parse_args(argv: Sequence[str]) -> tuple[Path, str, list[str]]:\n    parser = argparse.ArgumentParser(\n        description="Build the signed Capture app inside one root-supervised output custody life and return its protected stage."\n    )\n    parser.add_argument("--app-relative", default=str(DEFAULT_APP_RELATIVE))\n    parser.add_argument("--install-custody-helper-base64", required=True)\n    parser.add_argument("command", nargs=argparse.REMAINDER)\n    args = parser.parse_args(list(argv))\n    command = list(args.command)\n    if command and command[0] == "--":\n        command = command[1:]\n    return Path(args.app_relative), args.install_custody_helper_base64, command\n\n\ndef main(argv: Sequence[str] | None = None) -> int:\n    try:\n        app_relative, helper_source, command = _parse_args(sys.argv[1:] if argv is None else argv)\n        stage_root, fingerprint = run_custodied_build(\n            command,\n            app_relative=app_relative,\n            fingerprint_helper_base64=helper_source,\n        )\n        sys.stdout.write(f"{stage_root}\\t{fingerprint}\\n")\n        return 0\n    except BuildOriginCustodyError as error:\n        print(f"ERROR: {error}", file=sys.stderr)\n        return 78\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
ORIGIN_TEST_SOURCE = '#!/usr/bin/env python3\nfrom __future__ import annotations\n\nimport importlib.util\nimport os\nfrom pathlib import Path\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport unittest\n\nREPOSITORY = Path(__file__).resolve().parents[3]\nINSTALLER = REPOSITORY / "scripts/field/install_one_time_capture.command"\nORIGIN_HELPER = REPOSITORY / "scripts/ci/capture_signed_app_build_origin_custody.py"\nINSTALL_HELPER = REPOSITORY / "scripts/ci/capture_signed_app_install_custody.py"\n\n\ndef load(path: Path, name: str):\n    spec = importlib.util.spec_from_file_location(name, path)\n    if spec is None or spec.loader is None:\n        raise RuntimeError(f"could not load {path}")\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\nclass CaptureSignedAppPreStageOriginTests(unittest.TestCase):\n    def test_installer_promotes_only_root_supervisor_stage(self) -> None:\n        source = INSTALLER.read_text(encoding="utf-8")\n        helper_blob = \'BUILD_ORIGIN_CUSTODY_HELPER_BLOB="$(GIT_NO_REPLACE_OBJECTS=1 GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null /usr/bin/git rev-parse\'\n        sudo_supervisor = \'/usr/bin/sudo /usr/bin/python3 -I -c\'\n        result_parse = \'APP_INSTALL_STAGE_ROOT="${BUILD_ORIGIN_CUSTODY_RESULT%%$\\\'\\t\\\'*}"\'\n        switch = \'APP="$APP_INSTALL_STAGE"\'\n        verify = \'/usr/bin/python3 -I - verify-stage\'\n        codesign = \'/usr/bin/codesign --verify --deep --strict "$APP"\'\n        install = \'devicectl device install app --device "$COREDEVICE_ID" "$APP"\'\n\n        indexes = {}\n        for name, marker in (\n            ("helper_blob", helper_blob),\n            ("sudo_supervisor", sudo_supervisor),\n            ("result_parse", result_parse),\n            ("switch", switch),\n            ("verify", verify),\n            ("codesign", codesign),\n            ("install", install),\n        ):\n            indexes[name] = source.find(marker)\n            self.assertGreaterEqual(indexes[name], 0, f"missing {name} build-origin marker")\n\n        self.assertLess(indexes["helper_blob"], indexes["sudo_supervisor"])\n        self.assertLess(indexes["sudo_supervisor"], indexes["result_parse"])\n        self.assertLess(indexes["result_parse"], indexes["switch"])\n        self.assertLess(indexes["switch"], indexes["verify"])\n        self.assertLess(indexes["verify"], indexes["codesign"])\n        self.assertLess(indexes["codesign"], indexes["install"])\n\n        self.assertIn(\'DERIVED_PLACEHOLDER="__NEMBRA_PROTECTED_DERIVED__"\', source)\n        self.assertIn(\'--derivedDataPath "$DERIVED_PLACEHOLDER"\', source)\n        self.assertIn(\'--install-custody-helper-base64 "$SIGNED_APP_CUSTODY_HELPER_BASE64"\', source)\n        self.assertIn(\'STAGED_APP_TREE_SHA256="${BUILD_ORIGIN_CUSTODY_RESULT#*$\\\'\\t\\\'}"\', source)\n        self.assertIn(\'[[ "$VERIFIED_STAGE_TREE_SHA256" == "$STAGED_APP_TREE_SHA256" ]]\', source)\n        self.assertNotIn(\'APP="$DERIVED/Build/Products/Debug-iphoneos/Nembra Capture.app"\', source)\n        self.assertNotIn(\'SOURCE_APP_TREE_SHA256=\', source)\n        self.assertNotIn(\'/usr/bin/sudo /usr/bin/ditto --noacl "$APP" "$APP_INSTALL_STAGE"\', source)\n\n    def test_supervisor_revokes_sudo_then_isolates_locks_and_stages(self) -> None:\n        source = ORIGIN_HELPER.read_text(encoding="utf-8")\n        revoke = source.find("_invalidate_invoker_sudo(uid, gid, invoking_groups, child_env)")\n        prepare = source.find("derived_root = _prepare_derived(private_tmp, capability_gid)")\n        spawn = source.find("process = subprocess.Popen(", prepare)\n        terminate = source.find("_terminate_remaining_process_group(process.pid)", spawn)\n        lock_owner = source.find("os.chown(derived_root, 0, 0)", terminate)\n        lock_mode = source.find("os.chmod(derived_root, 0o700)", lock_owner)\n        source_fingerprint = source.find("source_fingerprint = str(fingerprint(source_app))", lock_mode)\n        stage = source.find("stage_root, stage_app = _copy_to_stage(source_app, private_tmp)", source_fingerprint)\n        stage_fingerprint = source.find("staged_fingerprint = str(fingerprint(stage_app))", stage)\n\n        for name, index in (\n            ("sudo revocation", revoke),\n            ("protected DerivedData creation", prepare),\n            ("guarded build spawn", spawn),\n            ("descendant retirement", terminate),\n            ("root lock owner", lock_owner),\n            ("root lock mode", lock_mode),\n            ("source fingerprint", source_fingerprint),\n            ("protected stage copy", stage),\n            ("stage fingerprint", stage_fingerprint),\n        ):\n            self.assertGreaterEqual(index, 0, f"missing {name}")\n\n        self.assertLess(revoke, prepare)\n        self.assertLess(prepare, spawn)\n        self.assertLess(spawn, terminate)\n        self.assertLess(terminate, lock_owner)\n        self.assertLess(lock_owner, lock_mode)\n        self.assertLess(lock_mode, source_fingerprint)\n        self.assertLess(source_fingerprint, stage)\n        self.assertLess(stage, stage_fingerprint)\n\n        self.assertIn("os.chown(derived, 0, capability_gid)", source)\n        self.assertIn("os.chmod(derived, 0o770)", source)\n        self.assertIn("child_groups = tuple(sorted(set(invoking_groups) | {capability_gid}))", source)\n        self.assertIn(\'["/usr/bin/sudo", "-K"]\', source)\n        self.assertIn(\'["/usr/bin/sudo", "-n", "/usr/bin/true"]\', source)\n        self.assertIn(\'["/usr/bin/ditto", "--noacl"\', source)\n        self.assertIn("if staged_fingerprint != source_fingerprint:", source)\n        self.assertIn("shutil.rmtree(derived_root, ignore_errors=True)", source)\n\n    def test_placeholder_is_exactly_single_use(self) -> None:\n        helper = load(ORIGIN_HELPER, "capture_signed_app_build_origin_custody")\n        derived = Path("/private/tmp/example")\n        self.assertEqual(\n            helper._replace_derived_placeholder(\n                ["tool", helper.DERIVED_PLACEHOLDER],\n                derived,\n            ),\n            ["tool", str(derived)],\n        )\n        with self.assertRaises(helper.BuildOriginCustodyError):\n            helper._replace_derived_placeholder(["tool"], derived)\n        with self.assertRaises(helper.BuildOriginCustodyError):\n            helper._replace_derived_placeholder(\n                ["tool", helper.DERIVED_PLACEHOLDER, helper.DERIVED_PLACEHOLDER],\n                derived,\n            )\n\n    def test_capability_gid_never_reuses_invoking_or_named_group(self) -> None:\n        helper = load(ORIGIN_HELPER, "capture_signed_app_build_origin_custody")\n        occupied = {group.gr_gid for group in helper.grp.getgrall()}\n        invoking = tuple(sorted(occupied))[:4] or (20,)\n        low = 1 << 29\n        candidate = low + 12345\n        while candidate in occupied or candidate in invoking:\n            candidate += 1\n        selected = helper._choose_capability_gid(\n            invoking,\n            randbelow=lambda _: candidate - low,\n        )\n        self.assertEqual(selected, candidate)\n        self.assertNotIn(selected, occupied)\n        self.assertNotIn(selected, invoking)\n\n    def test_external_replacement_after_handoff_cannot_change_promoted_stage(self) -> None:\n        install = load(INSTALL_HELPER, "capture_signed_app_install_custody_for_origin")\n        with tempfile.TemporaryDirectory(prefix="nembra-origin-model-") as temporary:\n            root = Path(temporary)\n            isolated = root / "isolated/Nembra Capture.app"\n            isolated.mkdir(parents=True)\n            (isolated / "Info.plist").write_text("accepted build provenance\\n", encoding="utf-8")\n            (isolated / "Nembra Capture").write_bytes(b"ACCEPTED_XCODEBUILD_OUTPUT\\n")\n            build_fingerprint = install.fingerprint(isolated)\n\n            protected = root / "protected/Nembra Capture.app"\n            protected.parent.mkdir()\n            shutil.copytree(isolated, protected, symlinks=True)\n            promoted_fingerprint = install.fingerprint(protected)\n            self.assertEqual(promoted_fingerprint, build_fingerprint)\n\n            replacement = root / "replacement.app"\n            replacement.mkdir()\n            (replacement / "Info.plist").write_text("accepted build provenance\\n", encoding="utf-8")\n            (replacement / "Nembra Capture").write_bytes(b"SUBSTITUTED_AFTER_HANDOFF\\n")\n            shutil.rmtree(isolated)\n            os.rename(replacement, isolated)\n\n            self.assertNotEqual(install.fingerprint(isolated), build_fingerprint)\n            self.assertEqual(install.fingerprint(protected), build_fingerprint)\n\n    @unittest.skipUnless(sys.platform == "darwin" and os.geteuid() == 0, "requires root on macOS")\n    def test_real_macos_one_run_group_capability_blocks_same_uid_and_lock_revokes_capability(self) -> None:\n        helper = load(ORIGIN_HELPER, "capture_signed_app_build_origin_custody_macos")\n        user, uid, gid, _home, groups = helper._invoking_identity()\n        capability_gid = helper._choose_capability_gid(groups)\n        private_tmp = helper._require_real_private_tmp()\n        derived = helper._prepare_derived(private_tmp, capability_gid)\n        try:\n            normal_preexec = helper._drop_credentials(uid, gid, groups)\n            capability_groups = tuple(sorted(set(groups) | {capability_gid}))\n            capability_preexec = helper._drop_credentials(uid, gid, capability_groups)\n            target = derived / "proof.txt"\n\n            denied = subprocess.run(\n                ["/usr/bin/touch", str(target)],\n                preexec_fn=normal_preexec,\n                stdin=subprocess.DEVNULL,\n                stdout=subprocess.DEVNULL,\n                stderr=subprocess.DEVNULL,\n                check=False,\n            )\n            self.assertNotEqual(denied.returncode, 0, f"{user} unexpectedly reached root-owned capability DerivedData")\n\n            allowed = subprocess.run(\n                ["/usr/bin/touch", str(target)],\n                preexec_fn=capability_preexec,\n                stdin=subprocess.DEVNULL,\n                stdout=subprocess.DEVNULL,\n                stderr=subprocess.DEVNULL,\n                check=False,\n            )\n            self.assertEqual(allowed.returncode, 0)\n\n            os.chown(derived, 0, 0)\n            os.chmod(derived, 0o700)\n            revoked = subprocess.run(\n                ["/bin/sh", "-c", f"printf changed > {target!s}"],\n                preexec_fn=capability_preexec,\n                stdin=subprocess.DEVNULL,\n                stdout=subprocess.DEVNULL,\n                stderr=subprocess.DEVNULL,\n                check=False,\n            )\n            self.assertNotEqual(revoked.returncode, 0, "root lock failed to revoke the one-run build capability")\n        finally:\n            shutil.rmtree(derived, ignore_errors=True)\n\n\nif __name__ == "__main__":\n    unittest.main(verbosity=2)\n'
