MACOS_JOB = '\n  macos-build-origin-isolation:\n    name: Prove compiler-output capability isolation on real macOS\n    runs-on: macos-15\n    timeout-minutes: 5\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          ref: ${{ github.event.pull_request.head.sha || github.sha }}\n\n      - name: Bind build-origin evidence to exact checked-out source\n        shell: bash\n        env:\n          EXPECTED_HEAD_SHA: ${{ github.event.pull_request.head.sha || github.sha }}\n        run: |\n          set -euo pipefail\n          expected="$(printf \'%s\' "$EXPECTED_HEAD_SHA" | tr \'[:upper:]\' \'[:lower:]\')"\n          actual="$(git rev-parse HEAD | tr \'[:upper:]\' \'[:lower:]\')"\n          [[ "$expected" =~ ^[0-9a-f]{40}$ ]]\n          test "$actual" = "$expected"\n          test -z "$(git status --porcelain=v1 --untracked-files=all)"\n\n      - name: Prove one-run group capability and root lock\n        shell: bash\n        run: |\n          set -euo pipefail\n          /usr/bin/python3 -m py_compile \\\n            scripts/ci/capture_signed_app_build_origin_custody.py \\\n            scripts/ci/tests/test_capture_signed_app_pre_stage_origin.py\n          sudo /usr/bin/python3 -B -I scripts/ci/tests/test_capture_signed_app_pre_stage_origin.py\n          test -z "$(git status --porcelain=v1 --untracked-files=all)"\n'


def require_once(text: str, needle: str, label: str) -> None:
    count = text.count(needle)
    if count != 1:
        raise RuntimeError(f"{label} precondition count was {count}, expected exactly one")


def replace_once(text: str, old: str, new: str, label: str) -> str:
    require_once(text, old, label)
    return text.replace(old, new, 1)


def patch_installer() -> None:
    source = INSTALLER.read_text(encoding="utf-8")
    start_marker = 'DERIVED="${TMPDIR:-/tmp}/NembraAuthenticatedCaptureDerived"'
    end_marker = 'APP_INFO_PLIST="$APP/Info.plist"'
    require_once(source, start_marker, "installer legacy DerivedData authority start")
    require_once(source, end_marker, "installer provenance readback boundary")
    start = source.index(start_marker)
    end = source.index(end_marker)
    vulnerable = source[start:end]
    required_vulnerable_markers = (
        'APP="$DERIVED/Build/Products/Debug-iphoneos/Nembra Capture.app"',
        'SOURCE_APP_TREE_SHA256=',
        '/usr/bin/sudo /usr/bin/ditto --noacl "$APP" "$APP_INSTALL_STAGE"',
        '/usr/bin/sudo -K',
    )
    for marker in required_vulnerable_markers:
        if marker not in vulnerable:
            raise RuntimeError(f"installer legacy origin seam marker disappeared: {marker}")
    source = source[:start] + NEW_INSTALLER_BLOCK + "\n\n" + source[end:]
    source = source.replace(
        'unset SOURCE_APP_TREE_SHA256 STAGED_APP_TREE_SHA256 SIGNED_APP_CUSTODY_HELPER_PATH SIGNED_APP_CUSTODY_HELPER_BLOB SIGNED_APP_CUSTODY_HELPER_BASE64 APP_INSTALL_STAGE',
        'unset STAGED_APP_TREE_SHA256 SIGNED_APP_CUSTODY_HELPER_PATH SIGNED_APP_CUSTODY_HELPER_BLOB SIGNED_APP_CUSTODY_HELPER_BASE64 BUILD_ORIGIN_CUSTODY_HELPER_PATH BUILD_ORIGIN_CUSTODY_HELPER_BLOB BUILD_ORIGIN_CUSTODY_HELPER_BASE64 APP_INSTALL_STAGE',
    )
    if 'APP="$DERIVED/Build/Products/Debug-iphoneos/Nembra Capture.app"' in source:
        raise RuntimeError("installer still self-authorizes mutable DerivedData after materialization")
    INSTALLER.write_text(source, encoding="utf-8")


